use sqlparser::dialect::{GenericDialect, PostgreSqlDialect};
use sqlparser::parser::Parser;

fn main() {
    let pg = PostgreSqlDialect {};
    let g = GenericDialect {};

    let ok = [
        "SELECT a = ANY(b OR c)",
        "SELECT a = ANY(b AND c)",
        "SELECT a = ANY(NOT b)",
        "SELECT a = ANY(b = c)",
        "SELECT a = ANY((b OR c))",
        "SELECT a = ANY(SELECT b FROM t) + 1",
        "SELECT a = ANY(b) + 1",
        "SELECT a = ANY(SELECT b FROM t) AND c",
        "SELECT a = ANY(b) OR c",
        "SELECT a = ANY(b) IS NULL",
        "SELECT a = ANY(b), c FROM t",
        "SELECT a = ALL(WITH x AS (SELECT 1) SELECT * FROM x)",
        "SELECT a = SOME(SELECT b FROM t WHERE c UNION SELECT d FROM t)",
        "SELECT a = ANY(SELECT arr FROM t)",
        "SELECT a = ANY((SELECT arr FROM t))",
        "SELECT a = ANY((SELECT x) + 1)",
        "SELECT a = ANY((b))",
    ];
    for sql in ok {
        for d in [&pg as &dyn sqlparser::dialect::Dialect, &g] {
            let ast = Parser::parse_sql(d, sql).unwrap_or_else(|e| panic!("FAIL {sql}: {e}"));
            let out = ast[0].to_string();
            let ast2 = Parser::parse_sql(d, &out).unwrap_or_else(|e| panic!("REPARSE FAIL {out}: {e}"));
            assert_eq!(ast, ast2, "roundtrip mismatch {sql} -> {out}");
            let pretty = format!("{:#}", ast[0]);
            let ast3 = Parser::parse_sql(d, &pretty).unwrap_or_else(|e| panic!("PRETTY REPARSE FAIL {pretty}: {e}"));
            assert_eq!(ast, ast3, "pretty roundtrip mismatch {sql}");
            println!("OK  {sql}\n -> {out}");
        }
    }

    // SOME must not be rewritten to ANY
    let ast = Parser::parse_sql(&pg, "SELECT a = SOME(b)").unwrap();
    assert_eq!(ast[0].to_string(), "SELECT a = SOME(b)");
    // subquery form distinction
    let direct = Parser::parse_sql(&pg, "SELECT a = ANY(SELECT arr FROM t)").unwrap();
    let grouped = Parser::parse_sql(&pg, "SELECT a = ANY((SELECT arr FROM t))").unwrap();
    assert_ne!(direct, grouped);
    assert_eq!(direct[0].to_string(), "SELECT a = ANY(SELECT arr FROM t)");
    assert_eq!(grouped[0].to_string(), "SELECT a = ANY((SELECT arr FROM t))");
    // +1 applies to the whole comparison
    let ast = Parser::parse_sql(&pg, "SELECT a = ANY(SELECT b FROM t) + 1").unwrap();
    assert_eq!(ast[0].to_string(), "SELECT (a = ANY(SELECT b FROM t)) + 1");
    let ast = Parser::parse_sql(&pg, "SELECT a = ANY(b) + 1").unwrap();
    assert_eq!(ast[0].to_string(), "SELECT (a = ANY(b)) + 1");

    let err = [
        "SELECT a = ANY()",
        "SELECT a = ANY b",
        "SELECT a = ANY(b",
        "SELECT a = ANY(b, c)",
        "SELECT a + ANY(b)",
        "SELECT a = ANY(b; SELECT (1)",
    ];
    for sql in err {
        assert!(Parser::parse_sql(&pg, sql).is_err(), "should fail: {sql}");
        assert!(Parser::parse_sql(&g, sql).is_err(), "should fail (generic): {sql}");
        println!("ERR OK  {sql}");
    }
    println!("all checks passed");
}
EOF
