use sqlparser::ast::{BinaryOperator, Expr, SelectItem, Statement};
use sqlparser::dialect::{GenericDialect, PostgreSqlDialect};
use sqlparser::parser::Parser;

fn projection_expr(sql: &str) -> Expr {
    let ast = Parser::parse_sql(&PostgreSqlDialect {}, sql).unwrap();
    match &ast[0] {
        Statement::Query(q) => match q.body.as_ref() {
            sqlparser::ast::SetExpr::Select(s) => match &s.projection[0] {
                SelectItem::UnnamedExpr(e) => e.clone(),
                _ => panic!("unexpected"),
            },
            _ => panic!("unexpected"),
        },
        _ => panic!("unexpected"),
    }
}

fn main() {
    // + 1 applies to the whole quantified comparison, not the operand
    match projection_expr("SELECT a = ANY(SELECT b FROM t) + 1") {
        Expr::BinaryOp { left, op: BinaryOperator::Plus, .. } => {
            assert!(matches!(left.as_ref(), Expr::AnyOp { .. }), "left: {left:?}");
        }
        e => panic!("unexpected: {e:?}"),
    }
    match projection_expr("SELECT a = ANY(b) + 1") {
        Expr::BinaryOp { left, op: BinaryOperator::Plus, .. } => {
            assert!(matches!(left.as_ref(), Expr::AnyOp { .. }), "left: {left:?}");
        }
        e => panic!("unexpected: {e:?}"),
    }
    // direct subquery vs parenthesized scalar subquery
    match projection_expr("SELECT a = ANY(SELECT arr FROM t)") {
        Expr::AnyOp { right, is_some, .. } => {
            assert!(matches!(right.as_ref(), Expr::Subquery(_)), "right: {right:?}");
            assert!(!is_some);
        }
        e => panic!("unexpected: {e:?}"),
    }
    match projection_expr("SELECT a = ANY((SELECT arr FROM t))") {
        Expr::AnyOp { right, .. } => match right.as_ref() {
            Expr::Nested(inner) => assert!(matches!(inner.as_ref(), Expr::Subquery(_))),
            other => panic!("expected Nested, got {other:?}"),
        },
        e => panic!("unexpected: {e:?}"),
    }
    // SOME preserved
    match projection_expr("SELECT a = SOME(b)") {
        Expr::AnyOp { is_some, .. } => assert!(is_some),
        e => panic!("unexpected: {e:?}"),
    }
    // full expression operand
    match projection_expr("SELECT a = ANY(b OR c)") {
        Expr::AnyOp { right, .. } => assert!(
            matches!(right.as_ref(), Expr::BinaryOp { op: BinaryOperator::Or, .. }),
            "right: {right:?}"
        ),
        e => panic!("unexpected: {e:?}"),
    }
    // ALL / SOME share the same boundary rules
    for (sql, is_all) in [("SELECT a = ALL(SELECT b FROM t) + 1", true), ("SELECT a = SOME(SELECT b FROM t) + 1", false)] {
        match projection_expr(sql) {
            Expr::BinaryOp { left, op: BinaryOperator::Plus, .. } => {
                if is_all {
                    assert!(matches!(left.as_ref(), Expr::AllOp { .. }));
                } else {
                    assert!(matches!(left.as_ref(), Expr::AnyOp { is_some: true, .. }));
                }
            }
            e => panic!("unexpected: {e:?}"),
        }
    }
    // GenericDialect accepts ANY(b OR c)
    let g = GenericDialect {};
    assert!(Parser::parse_sql(&g, "SELECT a = ANY(b OR c)").is_ok());
    // LIKE ANY untouched
    assert!(Parser::parse_sql(&g, "SELECT * FROM x WHERE a LIKE ANY ('%Jo%oe%', 'T%e')").is_ok());
    println!("AST checks passed");
}
EOF
