        },
        other => panic!("expected AnyOp, got {other:?}"),
    }
    assert_ne!(direct, grouped);
    verified_stmt("SELECT a = ALL((SELECT arr FROM t))");
    verified_stmt("SELECT a = SOME((SELECT arr FROM t))");
