use sqlparser::dialect::PostgreSqlDialect;
use sqlparser::parser::Parser;
fn main() {
    let pg = PostgreSqlDialect {};
    for sql in [
        "SELECT a = ANY((WITH x AS (SELECT 1) SELECT * FROM x))",
        "SELECT a = ANY(SELECT b FROM t WHERE c IN (SELECT d FROM t2))",
        "SELECT a = ANY(SELECT b FROM t LIMIT 1)",
        "SELECT a = ANY(((SELECT 1)))",
        "SELECT a = ANY(ARRAY[1,2,3])",
        "SELECT a = ANY('{}')",
        "SELECT a = ANY(b::int[])",
        "SELECT a <> ALL(SELECT b FROM t) OR d IS NOT NULL",
    ] {
        let ast = Parser::parse_sql(&pg, sql).unwrap_or_else(|e| panic!("FAIL {sql}: {e}"));
        let out = ast[0].to_string();
        let ast2 = Parser::parse_sql(&pg, &out).unwrap_or_else(|e| panic!("REPARSE FAIL {out}: {e}"));
        assert_eq!(ast, ast2, "roundtrip mismatch: {sql} -> {out}");
        println!("OK {sql}\n -> {out}");
    }
}
